-- XMLELEMENT
SELECT
	XMLELEMENT(NAME foo, 'bar');

-- XMLFOREST
SELECT
	XMLFOREST(name AS item_name, price AS item_price)
FROM
	products;

-- XMLCONCAT
SELECT
	XMLCONCAT('<a/>', '<b/>');

-- XMLPI
SELECT
	XMLPI(NAME php, 'echo "hello";');

-- XMLSERIALIZE
SELECT
	XMLSERIALIZE(CONTENT doc AS text)
FROM
	docs;

SELECT
	XMLSERIALIZE(DOCUMENT doc AS varchar(100))
FROM
	docs;

SELECT
	XMLSERIALIZE(CONTENT doc AS text INDENT)
FROM
	docs;

